const vendor = new URL(input.url).hostname.includes('slack') ? 'Slack' : 
               new URL(input.url).hostname.split('.')[0];

const sourceUrl = new URL(input.url);

const retrievedAt = new Date();

const content = $('article').text_sane();

// Extract the exact excerpt from the first paragraph, removing struck-through dates
const firstParagraph = $('article p').first();
const clonedParagraph = firstParagraph.clone();
clonedParagraph.find('s').remove();
const excerpt = clonedParagraph.text_sane();

// Extract capability identifier from h1 heading (more reliable than first paragraph)
const h1Text = $('article h1').text_sane();
const methodMatch = h1Text.match(/([\w.]+)\s+method/i);
const capabilityIdentifier = methodMatch ? 'slack.' + methodMatch[1] : null;

const changeType = content.toLowerCase().includes('sunset') ? 'shutdown' : 
                   content.toLowerCase().includes('deprecat') ? 'deprecation' : 
                   'change';

// Extract November 12, 2025 - the first strong element NOT inside a strikethrough tag
const deadlineOriginal = $('article p:first-of-type strong').filter(function() {
  return !$(this).parent('s').length;
}).first().text_sane();

let deadlineIso = null;
if (deadlineOriginal) {
  const parsed = new Date(deadlineOriginal);
  if (!isNaN(parsed.getTime())) {
    deadlineIso = parsed;
  }
}

return {
  vendor,
  sourceUrl,
  retrievedAt,
  content,
  excerpt,
  capabilityIdentifier,
  changeType,
  deadlineOriginal,
  deadlineIso
};
